mapper.update:
UPDATE income_sources
SET account_id = #{accountId},
    payment_name = #{paymentName},
    payment_day = #{paymentDay},
    memo = #{memo},
    gross_amount = #{grossAmount}
WHERE id = #{id}
    AND user_id = #{userId}
    AND is_deleted = 0

UPDATE income_sources
SET is_deleted = 1,
    deleted_at = NOW()
WHERE id = #{id}
    AND user_id = #{userId}
    AND is_deleted = 0

mapper.select:
SELECT COUNT(*)
FROM accounts
WHERE id = #{accountId}
    AND user_id  = #{userId}
    AND is_active = TRUE
    AND is_deleted = 0
